[Form]
public class GUPRuleTable extends FormRun
{
    protected GUPPricingType pricingType;
    private Query inventTableQuery;
}

    public void init()
    {
        xArgs args = element.args();
        EnumId enumId = args.parmEnumType();

        if (enumId == enumNum(GUPPricingType) && args.parmEnum())
        {
            element.pricingType = args.parmEnum();
        }
        else
        {
            switch (args.menuItemName())
            {
                case menuItemDisplayStr(GUPTradeAgreementRule):
                    element.pricingType = GUPPricingType::TradeAgreement;
                    break;
            }
        }

        super();

        if (element.pricingType == GUPPricingType::TradeAgreement)
        {
            FormDesign formDesign = element.design();
            formDesign.caption("@GlobalUnifiedPricing:GUPRuletable_Caption_TradeAgreement");
        }

        inventTableQuery = new Query();
        inventTableQuery.addDataSource(tableNum(InventTable))
            .addRange(fieldNum(InventTable, RecId))
            .value(int2Str(-1));
    }

internal void refreshFormDatasource(GUPPricingAttributeSourceLevel _sourceLevel)
{
    switch (_sourceLevel)
    {
        case GUPPricingAttributeSourceLevel::Header:
            CustTable_ds.executeQuery();
            GUPPricingRuleHeader_ds.reread();
            break;
        case GUPPricingAttributeSourceLevel::Line:
            InventTable_ds.executeQuery();
            GUPPricingRuleLine_ds.reread();
            break;
    }
}

    private GUPPricingRule selectPriceAttributeGroup(GUPPricingRule _pricingRule)
    {
        Args args = new Args(formStr(GUPAddPriceAttributeGroup));
        args.parmEnumType(enumNum(GUPPricingAttributeSourceLevel));
        args.parmEnum(enum2int(_pricingRule.getSourceLevel()));
        args.record(_pricingRule);

        FormRun selectAttributeGrpForm = classFactory.formRunClass(args);
        selectAttributeGrpForm.init();
        selectAttributeGrpForm.run();
        selectAttributeGrpForm.wait();

        GUPPricingRule ret;

        if (formHasMethod(selectAttributeGrpForm, identifierStr(masterRecord)))
        {
            ret = selectAttributeGrpForm.masterRecord();
        }

        return ret;
    }

    public int active()
    {
        int ret;

        ret = super();
        QueryBuildDataSource qbdsRuleTbl = this.queryBuildDataSource();
        qbdsRuleTbl
            .addRange(fieldNum(GUPRuleTable, PricingType))
            .value(any2Str(element.pricingType));

        return ret;
    }

        public void create(boolean _append = false)
        {
            GUPRuleTable createdRuleTable;
            GUPPricingRuleBuilder createRule = new GUPPricingRuleBuilder_RuleTable(element.pricingType);

            createdRuleTable = createRule.createRecord();
            if (createdRuleTable)
            {
                super(_append);
                GUPRuleTable.data(createdRuleTable);
                this.positionToRecord(createdRuleTable);
            }
        }

        public void write()
        {
            super();
            
            if (!GUPRuleLine.LinePricingRule && GUPRuleLine.ProductCodeType != GUPGroupAll::All)
            {
                GUPPricingRule lineRule;
                lineRule.clear();

                lineRule = element.selectPriceAttributeGroup(lineRule);
                GUPRuleLine.LinePricingRule = lineRule.RecId;
                GUPRuleLine.update();

                this.positionToRecord(GUPRuleLine);
            }
        }

        public void create(boolean _append = false)
        {
            /*GUPPricingRuleBuilder createRule = new GUPPricingRuleBuilder_RuleLine(GUPRuleTable);
            GUPRuleLine createdRuleLine = createRule.createRecord();

            if (createdRuleLine)
            {
                super(_append);
                GUPRuleLine.data(createdRuleLine);
                this.positionToRecord(createdRuleLine);
            }*/

            super(_append);
        }

        public int active()
        {
            int ret = super();
			
			element.enableSelectLinePricingAttrGrpButton();
			
            GUPPricingRule rule = GUPPricingRuleLine_ds.cursor();

            if (rule.PriceAttributeGroup)
            {
                inventTableQuery = GUPPricingObjectQueryBuilder::constructFromPricingRule(rule).build();
                InventTable_ds.executeQuery();
            }

            return ret;
        }

    public int active()
    {
        int ret;

        ret = super();

        return ret;
    }

        public void clicked()
        {
            xMenuFunction menuFunction = this.menufunction();

            xArgs args = new Args(element);
            args.parmEnumType(enumNum(GUPPricingAttributeSourceLevel));
            args.parmEnum(enum2int(GUPPricingAttributeSourceLevel::Header));
            args.record(GUPPricingRuleHeader);

            menuFunction.run(args);

            GUPPricingRuleHeader_ds.reread();
            CustTable_ds.executeQuery();
        }

        public void clicked()
        {
            xMenuFunction menuFunction = this.menufunction();

            xArgs args = new Args(element);
            args.parmEnumType(enumNum(GUPPricingAttributeSourceLevel));
            args.parmEnum(enum2int(GUPPricingAttributeSourceLevel::Line));
           
            if (!gupRuleLine.linePricingRule)
            {
                ttsbegin;

                GUPPricingRule ruleLine;
                ruleLine.insert();

                gupRuleLine.linePricingRule = ruleLine.RecId;
                gupRuleLine.update();

                ttscommit;
            }

            args.record(GUPPricingRule::find(gupRuleLine.linePricingRule));

            menuFunction.run(args);

            GUPPricingRuleLine.reread();
            InventTable_ds.executeQuery();
        }
